export const envelope = [32, 46, 28];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 12;

  // Grid buffer to ensure deterministic single writes and fast lookup
  const grid = new Map();

  function key(x, y, z) {
    return (x << 16) | (y << 8) | z;
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid.set(key(x, y, z), { x, y, z, block });
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      const entry = grid.get(key(x, y, z));
      return entry ? entry.block : null;
    }
    return null;
  }

  // Theme resolution with robust fallbacks
  const T = api.theme;
  const stonePrimary = (T.stone && T.stone.primary) || "minecraft:calcite";
  const stoneAccent = (T.stone && T.stone.accent) || "minecraft:red_terracotta";
  const stoneStairs = (T.stone && T.stone.stairs) || "minecraft:stone_brick_stairs";
  const stoneSlab = (T.stone && T.stone.slab) || "minecraft:stone_brick_slab";
  const stoneWall = (T.stone && T.stone.wall) || "minecraft:stone_brick_wall";

  const groundRevet = (T.ground && T.ground.revetment) || (T.stone && T.stone.primary) || "minecraft:diorite";
  const groundPlinth = (T.ground && T.ground.plinth) || (T.stone && T.stone.accent) || "minecraft:stone_bricks";
  const groundPave = (T.ground && T.ground.pavement) || "minecraft:stone_bricks";
  const groundStairs = (T.ground && T.ground.stairs) || stoneStairs;
  const groundSlab = (T.ground && T.ground.slab) || stoneSlab;

  const woodPlanks = (T.wood && T.wood.planks) || "minecraft:spruce_planks";
  const woodLog = (T.wood && T.wood.log) || "minecraft:spruce_log";
  const woodStripped = (T.wood && T.wood.stripped) || "minecraft:stripped_spruce_log";
  const woodStairs = (T.wood && T.wood.stairs) || "minecraft:spruce_stairs";
  const woodSlab = (T.wood && T.wood.slab) || "minecraft:spruce_slab";
  const woodFence = (T.wood && T.wood.fence) || "minecraft:spruce_fence";
  const woodTrapdoor = (T.wood && T.wood.trapdoor) || "minecraft:spruce_trapdoor";

  const roofStairs = (T.roof && T.roof.stairs) || woodStairs;
  const roofSlab = (T.roof && T.roof.slab) || woodSlab;
  const roofSolid = (T.roof && T.roof.solid) || stoneAccent;

  function baseName(blockStr) {
    return blockStr.replace(/\[.*\]/, "");
  }

  function stair(base, facing, half = "bottom", shape = "straight") {
    return `${baseName(base)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slab(base, type = "bottom") {
    return `${baseName(base)}[type=${type}]`;
  }

  function log(base, axis = "y") {
    return `${baseName(base)}[axis=${axis}]`;
  }

  function trapdoor(base, facing = "north", half = "bottom", open = "false") {
    return `${baseName(base)}[facing=${facing},half=${half},open=${open}]`;
  }

  // --- 1. SUBSTRUCTURE & CONFORMING CLIFF FOUNDATION ---
  function isFootprint(x, z) {
    if (x >= 13 && x <= 18 && z >= 0 && z <= 3) return true; // Approach steps
    if (x >= 8 && x <= 23 && z >= 4 && z <= 7) return true;  // Front terrace
    if (x >= 6 && x <= 25 && z >= 7 && z <= 24) return true; // Main fortress body
    if (x >= 24 && x <= 30 && z >= 7 && z <= 16) return true; // East stupa terrace
    if (x >= 2 && x <= 6 && z >= 9 && z <= 18) return true;  // West cliff buttresses
    if (x >= 6 && x <= 25 && z >= 24 && z <= 27) return true; // Back cliff anchorage
    return false;
  }

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (!isFootprint(x, z)) continue;

      const rawH = api.heightAt(x, z);
      const groundY = Math.max(0, seatY + Math.floor(rawH));

      let targetY = seatY;
      if (z <= 3 && x >= 13 && x <= 18) {
        targetY = seatY - (3 - z);
      } else if (z >= 24) {
        targetY = Math.max(seatY, groundY);
      }

      // Fill foundation down to ground
      const minY = Math.min(groundY, targetY);
      for (let y = minY; y <= targetY; y++) {
        const isOuter = (x === 6 || x === 25 || z === 4 || z === 24 ||
                         x === 2 || x === 30 || z === 0 || z === 16);
        const block = isOuter ? (y % 2 === 0 ? groundRevet : groundPlinth) : groundPlinth;
        set(x, y, z, block);
      }

      // Flaring rock plinth skirt at ground contact
      if (groundY > 0 && groundY < seatY) {
        set(x, groundY, z, groundRevet);
      }
    }
  }

  // West cliff buttress diagonal support pillars reaching down to rock face
  const buttressX = [3, 5];
  const buttressZ = [10, 14, 18];
  for (const bx of buttressX) {
    for (const bz of buttressZ) {
      const gy = Math.max(0, seatY + Math.floor(api.heightAt(bx, bz)));
      for (let y = gy; y <= seatY + 2; y++) {
        set(bx, y, bz, groundRevet);
        set(bx + 1, y, bz, groundPlinth);
      }
      // Timber support brackets reaching up to cantilevered balcony floor at y=15
      set(bx, seatY + 3, bz, stair(woodStairs, "west", "top"));
      set(bx, seatY + 4, bz, log(woodLog, "x"));
      set(bx + 1, seatY + 3, bz, log(woodLog, "y"));
    }
  }

  // --- 2. FRONT APPROACH STAIRS & TERRACE ---
  // Steps rising north to south
  for (let z = 0; z <= 3; z++) {
    const yStep = seatY - (3 - z);
    for (let x = 14; x <= 17; x++) {
      set(x, yStep, z, stair(groundStairs, "north"));
    }
    set(13, yStep, z, groundPlinth);
    set(13, yStep + 1, z, stoneWall);
    set(18, yStep, z, groundPlinth);
    set(18, yStep + 1, z, stoneWall);
  }

  // Courtyard & Terrace floor
  for (let x = 8; x <= 23; x++) {
    for (let z = 4; z <= 6; z++) {
      set(x, seatY, z, groundPave);
    }
  }

  // Terrace parapets
  for (let x = 8; x <= 12; x++) {
    set(x, seatY + 1, 4, stoneWall);
    set(x, seatY + 2, 4, slab(stoneSlab));
  }
  for (let x = 19; x <= 23; x++) {
    set(x, seatY + 1, 4, stoneWall);
    set(x, seatY + 2, 4, slab(stoneSlab));
  }

  // Covered Prayer Wheel Gallery Colonnade (North front)
  const porticoPillars = [8, 10, 12, 19, 21, 23];
  for (const px of porticoPillars) {
    for (let y = seatY + 1; y <= seatY + 4; y++) {
      set(px, y, 4, log(woodLog, "y"));
    }
    set(px, seatY + 4, 5, log(woodLog, "z"));
  }

  // Prayer wheel drums & roof
  for (let x = 8; x <= 23; x++) {
    if (x >= 14 && x <= 17) continue; // Entrance gateway
    set(x, seatY + 4, 4, log(woodLog, "x"));
    set(x, seatY + 5, 4, stair(roofStairs, "north"));
    set(x, seatY + 5, 5, roofSlab);
    // Golden prayer wheels
    if (x % 2 === 1) {
      set(x, seatY + 1, 5, "minecraft:bell[facing=north]");
      set(x, seatY + 2, 5, woodFence);
      set(x, seatY + 3, 5, "minecraft:lantern[hanging=true]");
    }
  }

  // Grand Entrance Gate Portal at (14..17, seatY + 1..5, z=7)
  for (let y = seatY + 1; y <= seatY + 5; y++) {
    set(14, y, 7, log(woodLog, "y"));
    set(17, y, 7, log(woodLog, "y"));
  }
  set(15, seatY + 5, 7, log(woodLog, "x"));
  set(16, seatY + 5, 7, log(woodLog, "x"));
  set(15, seatY + 4, 7, trapdoor(woodTrapdoor, "north", "top"));
  set(16, seatY + 4, 7, trapdoor(woodTrapdoor, "north", "top"));
  set(15, seatY + 1, 7, "minecraft:air");
  set(16, seatY + 1, 7, "minecraft:air");
  set(15, seatY + 2, 7, "minecraft:air");
  set(16, seatY + 2, 7, "minecraft:air");
  set(15, seatY + 3, 7, "minecraft:air");
  set(16, seatY + 3, 7, "minecraft:air");

  // --- 3. MAIN DZONG LEVEL 1 — THE DUKHANG (ASSEMBLY HALL) ---
  // Floor at y = 12
  for (let x = 7; x <= 24; x++) {
    for (let z = 7; z <= 23; z++) {
      set(x, seatY, z, (x === 7 || x === 24 || z === 7 || z === 23) ? stoneAccent : woodPlanks);
    }
  }

  // Thick battered whitewashed masonry walls (y = 13 to 19)
  for (let y = seatY + 1; y <= seatY + 7; y++) {
    for (let x = 7; x <= 24; x++) {
      // North & South walls
      if (y < seatY + 6) {
        if (!(z_is_gate(x, y))) {
          set(x, y, 7, stonePrimary);
        }
        set(x, y, 23, stonePrimary);
      } else if (y === seatY + 6) {
        // Red Shambu Frieze band
        set(x, y, 7, stoneAccent);
        set(x, y, 23, stoneAccent);
      } else if (y === seatY + 7) {
        // Dark timber cornice band
        set(x, y, 7, log(woodStripped, "x"));
        set(x, y, 23, log(woodStripped, "x"));
      }
    }

    for (let z = 7; z <= 23; z++) {
      // West & East walls
      if (y < seatY + 6) {
        set(7, y, z, stonePrimary);
        set(24, y, z, stonePrimary);
      } else if (y === seatY + 6) {
        set(7, y, z, stoneAccent);
        set(24, y, z, stoneAccent);
      } else if (y === seatY + 7) {
        set(7, y, z, log(woodStripped, "z"));
        set(24, y, z, log(woodStripped, "z"));
      }
    }
  }

  function z_is_gate(x, y) {
    return (x === 15 || x === 16) && y <= seatY + 4;
  }

  // Windows in Level 1 walls
  const dukhangWinZ = [11, 15, 19];
  for (const wz of dukhangWinZ) {
    // East wall windows
    set(24, seatY + 3, wz, woodFence);
    set(24, seatY + 4, wz, woodFence);
    set(24, seatY + 5, wz, trapdoor(woodTrapdoor, "east", "top"));

    // West wall doorway & windows to cantilever balcony
    if (wz === 15) {
      // Doorway to balcony
      set(7, seatY + 1, 14, "minecraft:air");
      set(7, seatY + 2, 14, "minecraft:air");
      set(7, seatY + 3, 14, trapdoor(woodTrapdoor, "west", "top"));
      set(7, seatY + 1, 15, "minecraft:air");
      set(7, seatY + 2, 15, "minecraft:air");
      set(7, seatY + 3, 15, trapdoor(woodTrapdoor, "west", "top"));
    } else {
      set(7, seatY + 3, wz, woodFence);
      set(7, seatY + 4, wz, woodFence);
      set(7, seatY + 5, wz, trapdoor(woodTrapdoor, "west", "top"));
    }
  }

  // Projecting eaves and bracket overhang at y = 20
  for (let x = 6; x <= 25; x++) {
    set(x, seatY + 8, 6, stair(roofStairs, "north"));
    set(x, seatY + 8, 24, stair(roofStairs, "south"));
    set(x, seatY + 7, 6, stair(woodStairs, "north", "top"));
    set(x, seatY + 7, 24, stair(woodStairs, "south", "top"));
  }
  for (let z = 6; z <= 24; z++) {
    set(6, seatY + 8, z, stair(roofStairs, "west"));
    set(25, seatY + 8, z, stair(roofStairs, "east"));
    set(6, seatY + 7, z, stair(woodStairs, "west", "top"));
    set(25, seatY + 7, z, stair(woodStairs, "east", "top"));
  }

  // --- 4. WEST CANTILEVERED BALCONY (RABSAL WING) ---
  // Overhanging timber beams (y = 15)
  for (let x = 2; x <= 7; x++) {
    for (let z = 9; z <= 19; z++) {
      set(x, seatY + 3, z, woodPlanks);
    }
  }

  // Timber framework & viewing bays (y = 16..18)
  for (let z = 9; z <= 19; z++) {
    // Outer West wall (X = 2)
    if (z === 9 || z === 13 || z === 16 || z === 19) {
      for (let y = seatY + 4; y <= seatY + 6; y++) {
        set(2, y, z, log(woodLog, "y"));
      }
    } else {
      set(2, seatY + 4, z, trapdoor(woodTrapdoor, "west", "bottom"));
      set(2, seatY + 5, z, woodFence);
      set(2, seatY + 6, z, log(woodStripped, "z"));
    }
  }

  // North & South balcony walls
  for (let x = 3; x <= 6; x++) {
    set(x, seatY + 4, 9, woodPlanks);
    set(x, seatY + 5, 9, woodFence);
    set(x, seatY + 6, 9, log(woodStripped, "x"));

    set(x, seatY + 4, 19, woodPlanks);
    set(x, seatY + 5, 19, woodFence);
    set(x, seatY + 6, 19, log(woodStripped, "x"));
  }

  // Balcony roof eaves (y = 19..20)
  for (let z = 8; z <= 20; z++) {
    set(1, seatY + 7, z, stair(roofStairs, "west"));
    set(2, seatY + 7, z, roofSolid);
    set(2, seatY + 8, z, slab(roofSlab));
  }
  for (let x = 2; x <= 6; x++) {
    set(x, seatY + 7, 8, stair(roofStairs, "north"));
    set(x, seatY + 7, 20, stair(roofStairs, "south"));
  }

  // --- 5. EAST CHORTEN (STUPA) TERRACE ---
  // Terrace floor
  for (let x = 24; x <= 30; x++) {
    for (let z = 7; z <= 16; z++) {
      set(x, seatY, z, groundPave);
    }
  }

  // East Terrace parapet
  for (let z = 7; z <= 16; z++) {
    set(30, seatY + 1, z, stoneWall);
    set(30, seatY + 2, z, slab(stoneSlab));
  }
  for (let x = 24; x <= 30; x++) {
    set(x, seatY + 1, 7, stoneWall);
    set(x, seatY + 2, 7, slab(stoneSlab));
    set(x, seatY + 1, 16, stoneWall);
    set(x, seatY + 2, 16, slab(stoneSlab));
  }

  // The Great Chorten (Stupa) centered at (27, 11)
  const cx = 27;
  const cz = 11;

  // Plinth 5x5 (y = 13)
  for (let dx = -2; dx <= 2; dx++) {
    for (let dz = -2; dz <= 2; dz++) {
      set(cx + dx, seatY + 1, cz + dz, stonePrimary);
      if (Math.abs(dx) === 2 || Math.abs(dz) === 2) {
        let facing = "north";
        if (dz === -2) facing = "north";
        else if (dz === 2) facing = "south";
        else if (dx === -2) facing = "west";
        else if (dx === 2) facing = "east";
        set(cx + dx, seatY + 1, cz + dz, stair(stoneStairs, facing));
      }
    }
  }

  // Stepped plinth 3x3 (y = 14)
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      set(cx + dx, seatY + 2, cz + dz, stoneAccent);
    }
  }

  // Bumpa (Rounded dome) (y = 15..16)
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      set(cx + dx, seatY + 3, cz + dz, stonePrimary);
      if (Math.abs(dx) + Math.abs(dz) <= 1) {
        set(cx + dx, seatY + 4, cz + dz, stonePrimary);
      }
    }
  }

  // Harmika (y = 17)
  set(cx, seatY + 5, cz, stoneAccent);
  set(cx + 1, seatY + 5, cz, trapdoor(woodTrapdoor, "east", "top"));
  set(cx - 1, seatY + 5, cz, trapdoor(woodTrapdoor, "west", "top"));
  set(cx, seatY + 5, cz + 1, trapdoor(woodTrapdoor, "south", "top"));
  set(cx, seatY + 5, cz - 1, trapdoor(woodTrapdoor, "north", "top"));

  // Chhatravali (13 golden discs & spire) (y = 18..20)
  set(cx, seatY + 6, cz, "minecraft:gold_block");
  set(cx, seatY + 7, cz, woodFence);
  set(cx, seatY + 8, cz, woodFence);

  // Finial Jewel & Crescent (y = 21)
  set(cx, seatY + 9, cz, "minecraft:lantern[hanging=false]");

  // External ceremonial staircase up to Level 2 (East side)
  for (let i = 0; i <= 7; i++) {
    const sx = 23;
    const sz = 16 + Math.floor(i / 2);
    const sy = seatY + i;
    set(sx, sy, sz, stair(groundStairs, "south"));
    set(sx, sy - 1, sz, groundPlinth);
  }

  // --- 6. LEVEL 2 — UPPER SANCTUARY & SCRIPTURE LIBRARY (LHAKHANG) ---
  // Level 2 Floor at y = 20 (seatY + 8)
  for (let x = 8; x <= 23; x++) {
    for (let z = 8; z <= 22; z++) {
      set(x, seatY + 8, z, woodPlanks);
    }
  }

  // Roof walkway parapets around Level 2
  for (let x = 8; x <= 23; x++) {
    set(x, seatY + 9, 8, stoneWall);
  }

  // Inward battered whitewashed walls (y = 21 to 27)
  for (let y = seatY + 9; y <= seatY + 15; y++) {
    for (let x = 9; x <= 22; x++) {
      if (y < seatY + 14) {
        set(x, y, 9, stonePrimary);
        set(x, y, 21, stonePrimary);
      } else if (y === seatY + 14) {
        // Upper Red Shambu Frieze
        set(x, y, 9, stoneAccent);
        set(x, y, 21, stoneAccent);
      } else if (y === seatY + 15) {
        // Upper Timber Cornice
        set(x, y, 9, log(woodStripped, "x"));
        set(x, y, 21, log(woodStripped, "x"));
      }
    }

    for (let z = 9; z <= 21; z++) {
      if (y < seatY + 14) {
        set(9, y, z, stonePrimary);
        set(22, y, z, stonePrimary);
      } else if (y === seatY + 14) {
        set(9, y, z, stoneAccent);
        set(22, y, z, stoneAccent);
      } else if (y === seatY + 15) {
        set(9, y, z, log(woodStripped, "z"));
        set(22, y, z, log(woodStripped, "z"));
      }
    }
  }

  // Upper Windows & Balcony openings
  const upperWinX = [12, 15, 19];
  for (const ux of upperWinX) {
    if (ux === 15) {
      // North entrance door to upper library
      set(ux, seatY + 9, 9, "minecraft:air");
      set(ux + 1, seatY + 9, 9, "minecraft:air");
      set(ux, seatY + 10, 9, "minecraft:air");
      set(ux + 1, seatY + 10, 9, "minecraft:air");
      set(ux, seatY + 11, 9, trapdoor(woodTrapdoor, "north", "top"));
      set(ux + 1, seatY + 11, 9, trapdoor(woodTrapdoor, "north", "top"));
    } else {
      set(ux, seatY + 11, 9, woodFence);
      set(ux, seatY + 12, 9, woodFence);
      set(ux, seatY + 13, 9, trapdoor(woodTrapdoor, "north", "top"));
    }
  }

  // Upper South Windows
  set(12, seatY + 11, 21, woodFence);
  set(12, seatY + 12, 21, woodFence);
  set(19, seatY + 11, 21, woodFence);
  set(19, seatY + 12, 21, woodFence);

  // Upper East/West Windows
  set(9, seatY + 11, 15, woodFence);
  set(9, seatY + 12, 15, woodFence);
  set(22, seatY + 11, 15, woodFence);
  set(22, seatY + 12, 15, woodFence);

  // Upper bracket eaves (y = 28 / seatY + 16)
  for (let x = 8; x <= 23; x++) {
    set(x, seatY + 16, 8, stair(roofStairs, "north"));
    set(x, seatY + 16, 22, stair(roofStairs, "south"));
    set(x, seatY + 15, 8, stair(woodStairs, "north", "top"));
    set(x, seatY + 15, 22, stair(woodStairs, "south", "top"));
  }
  for (let z = 8; z <= 22; z++) {
    set(8, seatY + 16, z, stair(roofStairs, "west"));
    set(23, seatY + 16, z, stair(roofStairs, "east"));
    set(8, seatY + 15, z, stair(woodStairs, "west", "top"));
    set(23, seatY + 15, z, stair(woodStairs, "east", "top"));
  }

  // --- 7. LEVEL 3 — ROOF TERRACE & THE GOLDEN PAVILION (SERTHOK) ---
  // Roof Terrace Floor at y = 28 (seatY + 16)
  for (let x = 9; x <= 22; x++) {
    for (let z = 9; z <= 21; z++) {
      set(x, seatY + 16, z, stonePrimary);
    }
  }

  // Parapets around the top roof terrace
  for (let x = 9; x <= 22; x++) {
    set(x, seatY + 17, 9, stoneWall);
    set(x, seatY + 17, 21, stoneWall);
  }
  for (let z = 9; z <= 21; z++) {
    set(9, seatY + 17, z, stoneWall);
    set(22, seatY + 17, z, stoneWall);
  }

  // Four Corner Victory Banners (Dhvaja / Gyaltsen)
  const banners = [
    [9, 9], [22, 9], [9, 21], [22, 21]
  ];
  for (const [bx, bz] of banners) {
    set(bx, seatY + 17, bz, log(woodStripped, "y"));
    set(bx, seatY + 18, bz, stoneAccent);
    set(bx, seatY + 19, bz, "minecraft:gold_block");
    set(bx, seatY + 20, bz, "minecraft:bell[facing=north]");
  }

  // The Central Golden Pavilion Temple (Serthok)
  // Base at (12..19, 12..18)
  for (let x = 12; x <= 19; x++) {
    for (let z = 12; z <= 18; z++) {
      set(x, seatY + 16, z, woodPlanks);
    }
  }

  // Pavilion Pillars & Gilded Screen Walls (y = 29..32 / seatY + 17..20)
  for (let y = seatY + 17; y <= seatY + 20; y++) {
    // Corner posts
    set(12, y, 12, log(woodLog, "y"));
    set(19, y, 12, log(woodLog, "y"));
    set(12, y, 18, log(woodLog, "y"));
    set(19, y, 18, log(woodLog, "y"));

    // North & South walls
    for (let x = 13; x <= 18; x++) {
      if (y === seatY + 17) {
        set(x, y, 12, log(woodStripped, "x"));
        set(x, y, 18, log(woodStripped, "x"));
      } else if (y === seatY + 20) {
        set(x, y, 12, log(woodStripped, "x"));
        set(x, y, 18, log(woodStripped, "x"));
      } else {
        if (x === 15 || x === 16) {
          // Open doorway
          set(x, y, 12, "minecraft:air");
        } else {
          set(x, y, 12, woodFence);
        }
        set(x, y, 18, woodFence);
      }
    }

    // East & West walls
    for (let z = 13; z <= 17; z++) {
      if (y === seatY + 17 || y === seatY + 20) {
        set(12, y, z, log(woodStripped, "z"));
        set(19, y, z, log(woodStripped, "z"));
      } else {
        set(12, y, z, woodFence);
        set(19, y, z, woodFence);
      }
    }
  }

  // Serthok Golden Hip Roof (y = 33..36 / seatY + 21..24)
  // Flared lower eaves at y = 33
  for (let x = 11; x <= 20; x++) {
    set(x, seatY + 21, 11, stair(roofStairs, "north"));
    set(x, seatY + 21, 19, stair(roofStairs, "south"));
    set(x, seatY + 20, 11, stair(woodStairs, "north", "top"));
    set(x, seatY + 20, 19, stair(woodStairs, "south", "top"));
  }
  for (let z = 11; z <= 19; z++) {
    set(11, seatY + 21, z, stair(roofStairs, "west"));
    set(20, seatY + 21, z, stair(roofStairs, "east"));
    set(11, seatY + 20, z, stair(woodStairs, "west", "top"));
    set(20, seatY + 20, z, stair(woodStairs, "east", "top"));
  }

  // Tier 2 at y = 34
  for (let x = 12; x <= 19; x++) {
    set(x, seatY + 22, 12, stair(roofStairs, "north"));
    set(x, seatY + 22, 18, stair(roofStairs, "south"));
  }
  for (let z = 12; z <= 18; z++) {
    set(12, seatY + 22, z, stair(roofStairs, "west"));
    set(19, seatY + 22, z, stair(roofStairs, "east"));
  }
  for (let x = 13; x <= 18; x++) {
    for (let z = 13; z <= 17; z++) {
      set(x, seatY + 22, z, roofSolid);
    }
  }

  // Tier 3 at y = 35
  for (let x = 13; x <= 18; x++) {
    set(x, seatY + 23, 13, stair(roofStairs, "north"));
    set(x, seatY + 23, 17, stair(roofStairs, "south"));
  }
  for (let z = 13; z <= 17; z++) {
    set(13, seatY + 23, z, stair(roofStairs, "west"));
    set(18, seatY + 23, z, stair(roofStairs, "east"));
  }

  // Roof ridge cap at y = 36
  for (let x = 14; x <= 17; x++) {
    for (let z = 14; z <= 16; z++) {
      set(x, seatY + 24, z, "minecraft:gold_block");
    }
  }

  // Ganjira (Golden Finial Spire & Vase of Immortality) (y = 37..41 / seatY + 25..29)
  set(15, seatY + 25, 15, "minecraft:gold_block");
  set(16, seatY + 25, 15, "minecraft:gold_block");
  set(15, seatY + 26, 15, "minecraft:bell[facing=north]");
  set(16, seatY + 26, 15, "minecraft:bell[facing=south]");
  set(15, seatY + 27, 15, woodFence);
  set(16, seatY + 27, 15, woodFence);
  set(15, seatY + 28, 15, "minecraft:lantern[hanging=false]");
  set(16, seatY + 28, 15, "minecraft:lantern[hanging=false]");

  // --- 8. PRAYER FLAG STRINGS (LUNGTA) & ATMOSPHERE ---
  // Flag Masts
  const mastPositions = [
    [8, seatY + 1, 4, 8],     // Front West terrace
    [23, seatY + 1, 4, 8],    // Front East terrace
    [30, seatY + 1, 7, 10],   // East Stupa terrace
    [9, seatY + 17, 9, 8],    // Roof West
    [22, seatY + 17, 9, 8]    // Roof East
  ];

  for (const [mx, myBase, mz, mHeight] of mastPositions) {
    for (let dy = 0; dy < mHeight; dy++) {
      set(mx, myBase + dy, mz, dy < 2 ? log(woodLog, "y") : woodFence);
    }
  }

  // 3D Prayer Flag Lines connecting high peaks
  const flagColors = [
    "minecraft:blue_wool",
    "minecraft:white_wool",
    "minecraft:red_wool",
    "minecraft:lime_wool",
    "minecraft:yellow_wool"
  ];

  function drawFlagLine(x0, y0, z0, x1, y1, z1) {
    const dx = x1 - x0;
    const dy = y1 - y0;
    const dz = z1 - z0;
    const steps = Math.max(Math.abs(dx), Math.abs(dy), Math.abs(dz)) * 2;
    if (steps === 0) return;

    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const sag = Math.sin(t * Math.PI) * 1.5;
      const x = Math.round(x0 + dx * t);
      const y = Math.round(y0 + dy * t - sag);
      const z = Math.round(z0 + dz * t);

      if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
        if (!get(x, y, z) || get(x, y, z) === "minecraft:air") {
          const color = flagColors[Math.floor(i / 2) % flagColors.length];
          set(x, y, z, color);
        }
      }
    }
  }

  // String prayer lines across the fortress
  drawFlagLine(9, seatY + 24, 9, 15, seatY + 26, 15);
  drawFlagLine(22, seatY + 24, 9, 16, seatY + 26, 15);
  drawFlagLine(8, seatY + 8, 4, 8, seatY + 16, 8);
  drawFlagLine(23, seatY + 8, 4, 23, seatY + 16, 8);
  drawFlagLine(30, seatY + 10, 7, 23, seatY + 16, 9);
  drawFlagLine(9, seatY + 24, 21, 15, seatY + 26, 15);
  drawFlagLine(22, seatY + 24, 21, 16, seatY + 26, 15);

  // --- 9. SNOW DUSTING ON EXPOSED ROOFS & LEDGES ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      for (let y = H - 2; y >= 0; y--) {
        const blk = get(x, y, z);
        if (blk && !blk.includes("air") && !blk.includes("wool") && !blk.includes("fence") && !blk.includes("lantern") && !blk.includes("stairs")) {
          const above = get(x, y + 1, z);
          if (!above || above === "minecraft:air") {
            // Light dusting on exposed flat ledge corners
            if ((x + z + y) % 5 === 0) {
              set(x, y + 1, z, "minecraft:snow[layers=1]");
            }
          }
          break; // Stop at highest exposed block in column
        }
      }
    }
  }

  // --- 10. EMIT TO WORLD ---
  // Ensure interior volumes are guaranteed hollow air before emission
  const declaredInteriors = [
    { min: [8, seatY + 1, 8], max: [23, seatY + 7, 22], kind: "nave" },
    { min: [10, seatY + 9, 10], max: [21, seatY + 14, 20], kind: "vault" },
    { min: [3, seatY + 4, 10], max: [6, seatY + 6, 18], kind: "quarters" }
  ];

  for (const r of declaredInteriors) {
    for (let x = r.min[0]; x <= r.max[0]; x++) {
      for (let y = r.min[1]; y <= r.max[1]; y++) {
        for (let z = r.min[2]; z <= r.max[2]; z++) {
          grid.delete(key(x, y, z));
        }
      }
    }
  }

  // Deterministic emission: sorted by coordinates (Y, Z, X)
  const entries = Array.from(grid.values());
  entries.sort((a, b) => (a.y !== b.y ? a.y - b.y : a.z !== b.z ? a.z - b.z : a.x - b.x));

  for (let i = 0; i < entries.length; i++) {
    const e = entries[i];
    api.set(e.x, e.y, e.z, e.block);
  }

  return {
    name: "cliffside_dzong",
    seatY: seatY,
    anchors: {
      front: [15, seatY, 0],
      door: [15, seatY + 1, 7]
    },
    interiors: declaredInteriors
  };
}

