export const envelope = [9, 26, 9];

export default function build(api) {
  const [W, H, D] = api.size;
  const SY = 5; // Seat plane Y: accommodates foundation skirts on falling terrain
  const cx = 4;
  const cz = 4;

  const idx = api.instance.index;
  const rand = () => api.random();

  // Resolve palette roles from the world theme with robust fallbacks
  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";

  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:chiseled_stone_bricks";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";

  const groundPlinth = api.theme?.ground?.plinth || "minecraft:cobblestone";
  const wallCore = api.theme?.wall?.core || "minecraft:cobblestone";

  // Sacred 5-color Tibetan prayer flag sequence (Lungta: Space, Air, Fire, Water, Earth)
  const PRAYER_COLORS = [
    "minecraft:blue_wool",
    "minecraft:white_wool",
    "minecraft:red_wool",
    "minecraft:lime_wool",
    "minecraft:yellow_wool"
  ];

  // Helper functions for block state assembly
  function makeLog(baseBlock, axis = "y") {
    const name = baseBlock.split("[")[0];
    return `${name}[axis=${axis}]`;
  }

  function makeStair(baseBlock, facing, half = "bottom") {
    const name = baseBlock.split("[")[0];
    return `${name}[facing=${facing},half=${half}]`;
  }

  function makeSlab(baseBlock, type = "bottom") {
    const name = baseBlock.split("[")[0];
    return `${name}[type=${type}]`;
  }

  function stripState(baseBlock) {
    return baseBlock.split("[")[0];
  }

  // 3D Grid storage for deterministic assembly
  const grid = new Map();

  function setCell(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid.set(`${x},${y},${z}`, block);
  }

  function getCell(x, y, z) {
    return grid.get(`${x},${y},${z}`) || null;
  }

  // Instance variation parameters
  const mastHeight = SY + 14 + (idx % 4); // Y = 19 to 22
  const finialStyle = idx % 4;
  const sagAmount = 0.65 + (rand() * 0.45);
  const colorOffsetBase = Math.floor(rand() * 5);
  const hasIncenseHearth = (idx % 2 === 0);
  const hasPrayerNiches = (idx % 2 === 1);
  const isEightWay = (idx % 3 !== 1);

  // -------------------------------------------------------------
  // 1. STEPPED MANI STONE CAIRN (LHATSE / CHORTEN BASE)
  // -------------------------------------------------------------

  // Tier 0: Broad 9x9 Plinth Foundation (y = SY)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const d = Math.abs(x - cx) + Math.abs(z - cz);
      if (d <= 6) {
        setCell(x, SY, z, groundPlinth);
      }
    }
  }

  // Tier 1: 7x7 Stepped Base Platform (y = SY + 1)
  for (let x = 1; x <= 7; x++) {
    for (let z = 1; z <= 7; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx + dz <= 5) {
        // Outer edge coping stairs
        if (z === 1 && dx <= 2) {
          setCell(x, SY + 1, z, makeStair(stoneStairs, "north"));
        } else if (z === 7 && dx <= 2) {
          setCell(x, SY + 1, z, makeStair(stoneStairs, "south"));
        } else if (x === 1 && dz <= 2) {
          setCell(x, SY + 1, z, makeStair(stoneStairs, "west"));
        } else if (x === 7 && dz <= 2) {
          setCell(x, SY + 1, z, makeStair(stoneStairs, "east"));
        } else {
          setCell(x, SY + 1, z, stonePrimary);
        }
      }
    }
  }

  // Four Satellite Corner Anchor Cairns (NW, NE, SW, SE)
  const cornerAnchors = [
    [1, 1], [7, 1], [1, 7], [7, 7]
  ];
  for (const [ax, az] of cornerAnchors) {
    setCell(ax, SY + 1, az, stonePrimary);
    setCell(ax, SY + 2, az, stripState(stoneWall));
    setCell(ax, SY + 3, az, makeSlab(stoneSlab, "bottom"));
  }

  // Four Cardinal Edge Anchor Piers (N, S, E, W)
  const cardinalAnchors = [
    [4, 0], [4, 8], [0, 4], [8, 4]
  ];
  for (const [ax, az] of cardinalAnchors) {
    setCell(ax, SY + 1, az, stonePrimary);
    setCell(ax, SY + 2, az, makeSlab(stoneSlab, "bottom"));
  }

  // Tier 2: 5x5 Inscribed Mani Stone Tier (y = SY + 2)
  for (let x = 2; x <= 6; x++) {
    for (let z = 2; z <= 6; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 2 && dz <= 2) {
        // Outer face carved tablets and niches
        if (x === 4 && z === 2) {
          setCell(x, SY + 2, z, hasPrayerNiches ? "minecraft:lantern[hanging=false]" : stoneAccent);
        } else if (x === 4 && z === 6) {
          setCell(x, SY + 2, z, stoneAccent);
        } else if ((x === 2 || x === 6) && z === 4) {
          setCell(x, SY + 2, z, stoneAccent);
        } else {
          setCell(x, SY + 2, z, stonePrimary);
        }
      }
    }
  }

  // Tier 3: 5x5 Stone Coping (y = SY + 3)
  for (let x = 2; x <= 6; x++) {
    for (let z = 2; z <= 6; z++) {
      if (z === 2) setCell(x, SY + 3, z, makeStair(stoneStairs, "north"));
      else if (z === 6) setCell(x, SY + 3, z, makeStair(stoneStairs, "south"));
      else if (x === 2) setCell(x, SY + 3, z, makeStair(stoneStairs, "west"));
      else if (x === 6) setCell(x, SY + 3, z, makeStair(stoneStairs, "east"));
      else setCell(x, SY + 3, z, stonePrimary);
    }
  }

  // Tier 4: 3x3 Upper Platform & Incense Hearth (y = SY + 4)
  for (let x = 3; x <= 5; x++) {
    for (let z = 3; z <= 5; z++) {
      setCell(x, SY + 4, z, stonePrimary);
    }
  }
  if (hasIncenseHearth) {
    // Sang-khang (juniper burner) on the south face
    setCell(4, SY + 4, 5, stoneAccent);
    setCell(4, SY + 5, 5, stripState(stoneWall));
  }

  // Tier 5: 3x3 Mast Socket Collar (y = SY + 5)
  setCell(cx, SY + 5, cz, makeLog(woodLog, "y"));
  setCell(cx, SY + 5, cz - 1, makeStair(woodStairs, "south"));
  setCell(cx, SY + 5, cz + 1, makeStair(woodStairs, "north"));
  setCell(cx - 1, SY + 5, cz, makeStair(woodStairs, "east"));
  setCell(cx + 1, SY + 5, cz, makeStair(woodStairs, "west"));

  // -------------------------------------------------------------
  // 2. CENTRAL WEATHERED TIMBER MAST (DARCHOR)
  // -------------------------------------------------------------

  const mastLog = (idx % 2 === 0) ? woodLog : woodStripped;
  for (let y = SY + 1; y <= mastHeight; y++) {
    setCell(cx, y, cz, makeLog(mastLog, "y"));
  }

  // Mid-Mast Yardarm & Prayer Wheel Ring (y = SY + 8)
  const midY = SY + 8;
  setCell(cx - 1, midY, cz, woodFence);
  setCell(cx + 1, midY, cz, woodFence);
  // Draped ceremonial white khata scarf
  setCell(cx - 1, midY - 1, cz, "minecraft:white_wool");
  setCell(cx + 1, midY - 1, cz, "minecraft:white_wool");

  // Upper Flag Spreader Crossarm (y = mastHeight - 2)
  const spreadY = mastHeight - 2;
  setCell(cx, spreadY, cz - 1, woodFence);
  setCell(cx, spreadY, cz + 1, woodFence);
  setCell(cx - 1, spreadY, cz, woodFence);
  setCell(cx + 1, spreadY, cz, woodFence);

  // Mast Finial Apex
  const topY = mastHeight + 1;
  if (finialStyle === 0) {
    // Gilded Gyaltsen (Victory Banner)
    setCell(cx, mastHeight, cz, "minecraft:white_wool");
    setCell(cx, topY, cz, "minecraft:red_wool");
    setCell(cx, topY + 1, cz, "minecraft:yellow_wool");
  } else if (finialStyle === 1) {
    // Trishula / Sun & Moon Disc
    setCell(cx, mastHeight, cz, stripState(stoneWall));
    setCell(cx, topY, cz, "minecraft:lantern[hanging=false]");
  } else if (finialStyle === 2) {
    // Juniper Bough & Windhorse Streamer
    setCell(cx, mastHeight, cz, "minecraft:spruce_leaves[persistent=true]");
    setCell(cx, topY, cz, "minecraft:spruce_leaves[persistent=true]");
    setCell(cx, topY, cz - 1, "minecraft:white_wool");
  } else {
    // Sacred Chorten Spire
    setCell(cx, mastHeight, cz, stripState(stoneWall));
    setCell(cx, topY, cz, stripState(stoneWall));
    setCell(cx, topY + 1, cz, makeSlab(stoneSlab, "bottom"));
  }

  // -------------------------------------------------------------
  // 3. RADIATING 6-CONNECTED PRAYER FLAG LINES (LUNGTA STREAMERS)
  // -------------------------------------------------------------

  function drawFlagStreamer(p1, p2, sag, colorOffset) {
    const numSamples = 60;
    let prev = null;

    for (let s = 0; s <= numSamples; s++) {
      const t = s / numSamples;
      const xt = p1[0] + (p2[0] - p1[0]) * t;
      const zt = p1[2] + (p2[2] - p1[2]) * t;
      const ytStraight = p1[1] + (p2[1] - p1[1]) * t;
      const yt = ytStraight - 4 * sag * t * (1 - t);

      const cur = [
        Math.round(xt),
        Math.round(yt),
        Math.round(zt)
      ];

      const band = Math.floor(t * 11 + colorOffset);
      const color = PRAYER_COLORS[((band % 5) + 5) % 5];

      if (prev === null) {
        if (!getCell(cur[0], cur[1], cur[2])) {
          setCell(cur[0], cur[1], cur[2], color);
        }
        prev = cur;
      } else {
        let bx = prev[0];
        let by = prev[1];
        let bz = prev[2];

        // Step 6-connected Manhattan voxels between consecutive points
        while (bx !== cur[0] || by !== cur[1] || bz !== cur[2]) {
          const dx = cur[0] - bx;
          const dy = cur[1] - by;
          const dz = cur[2] - bz;

          if (Math.abs(dx) >= Math.abs(dy) && Math.abs(dx) >= Math.abs(dz)) {
            bx += Math.sign(dx);
          } else if (Math.abs(dy) >= Math.abs(dz)) {
            by += Math.sign(dy);
          } else {
            bz += Math.sign(dz);
          }

          if (!getCell(bx, by, bz)) {
            setCell(bx, by, bz, color);
          }
        }
        prev = cur;
      }
    }
  }

  const mastTopAnchor = [cx, mastHeight - 1, cz];

  // Primary diagonal streamer lines (to 4 corner anchor stupas)
  drawFlagStreamer(mastTopAnchor, [1, SY + 3, 1], sagAmount, colorOffsetBase);
  drawFlagStreamer(mastTopAnchor, [7, SY + 3, 1], sagAmount, colorOffsetBase + 1);
  drawFlagStreamer(mastTopAnchor, [7, SY + 3, 7], sagAmount, colorOffsetBase + 2);
  drawFlagStreamer(mastTopAnchor, [1, SY + 3, 7], sagAmount, colorOffsetBase + 3);

  // Cardinal streamer lines (to 4 edge anchor piers)
  if (isEightWay) {
    drawFlagStreamer(mastTopAnchor, [4, SY + 2, 0], sagAmount * 0.9, colorOffsetBase + 4);
    drawFlagStreamer(mastTopAnchor, [8, SY + 2, 4], sagAmount * 0.9, colorOffsetBase + 1);
    drawFlagStreamer(mastTopAnchor, [4, SY + 2, 8], sagAmount * 0.9, colorOffsetBase + 2);
    drawFlagStreamer(mastTopAnchor, [0, SY + 2, 4], sagAmount * 0.9, colorOffsetBase + 3);
  } else {
    // 6-way cliffside sweep
    drawFlagStreamer(mastTopAnchor, [4, SY + 2, 0], sagAmount * 0.85, colorOffsetBase + 4);
    drawFlagStreamer(mastTopAnchor, [4, SY + 2, 8], sagAmount * 0.85, colorOffsetBase + 2);
  }

  // -------------------------------------------------------------
  // 4. TERRAIN CONFORMITY & FOUNDATION SKIRT (RULE 6)
  // -------------------------------------------------------------

  // Find all occupied columns where the structure stands
  const occupiedCols = new Set();
  for (const key of grid.keys()) {
    const [x, y, z] = key.split(",").map(Number);
    if (y >= SY) {
      occupiedCols.add(`${x},${z}`);
    }
  }

  // Fill foundation downward or upward to meet local terrain height exactly
  for (const col of occupiedCols) {
    const [x, z] = col.split(",").map(Number);
    const terrainH = Math.round(api.heightAt(x, z));
    const groundY = Math.max(0, Math.min(H - 1, SY + terrainH));

    if (groundY < SY) {
      // Ground falls away: build foundation skirt down to terrain
      for (let y = groundY; y < SY; y++) {
        if (!getCell(x, y, z)) {
          const fillBlock = (y === groundY) ? groundPlinth : (y % 2 === 0 ? stonePrimary : wallCore);
          setCell(x, y, z, fillBlock);
        }
      }
    } else if (groundY > SY) {
      // Ground rises: build plinth upward to meet rising rock
      for (let y = SY; y <= groundY; y++) {
        if (!getCell(x, y, z)) {
          setCell(x, y, z, groundPlinth);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 5. DETERMINISTIC EMISSION
  // -------------------------------------------------------------

  // Sort keys deterministically: y ascending, then z, then x
  const sortedKeys = Array.from(grid.keys()).sort((a, b) => {
    const [ax, ay, az] = a.split(",").map(Number);
    const [bx, by, bz] = b.split(",").map(Number);
    if (ay !== by) return ay - by;
    if (az !== bz) return az - bz;
    return ax - bx;
  });

  for (const key of sortedKeys) {
    const [x, y, z] = key.split(",").map(Number);
    const block = grid.get(key);
    if (block) {
      api.set(x, y, z, block);
    }
  }

  return {
    name: "prayer_flag_mast",
    seatY: SY,
    anchors: {
      front: [4, SY, 0],
      base: [4, SY, 4],
      summit: [4, mastHeight + 1, 4]
    }
  };
}
